16	/// * `1`, a bool indicating whether the message contained data (not just keepalive)
17	/// * `2`, a bool indicating whether the message was transmitted (i.e. did the peer have an associated endpoint?)
18	pub trait Callback<T>: Fn(&T, usize, bool) + Sync + Send + 'static {}
