46	impl fmt::Display for RouterError {
47	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
48	        match self {
49	            RouterError::NoCryptoKeyRoute => write!(f, "No cryptokey route configured for subnet"),
50	            RouterError::MalformedTransportMessage => write!(f, "Transport header is malformed"),
