39	    ) -> ReceiveJob<E, C, T, B> {
40	        ReceiveJob(Arc::new(Inner {
41	            ready: AtomicBool::new(false),
42	            buffer: Mutex::new((Some(endpoint), buffer)),
43	            state,
44	        }))
45	    }
46	}
