48	impl<E: Endpoint, C: Callbacks, T: tun::Writer, B: udp::Writer<E>> ParallelJob
49	    for ReceiveJob<E, C, T, B>
50	{
51	    fn queue(&self) -> &Queue<Self> {
52	        &self.0.state.peer.inbound
53	    }
54	
55	    /* The parallel section of an incoming job:
56	     *
57	     * - Decryption.
58	     * - Crypto-key routing lookup.
59	     *
60	     * Note: We truncate the message buffer to 0 bytes in case of authentication failure
61	     * or crypto-key routing failure (attempted impersonation).
62	     *
63	     * Note: We cannot do replay protection in the parallel job,
64	     * since this can cause dropping of packets (leaving the window) due to scheduling.
65	     */
66	    fn parallel_work(&self) {
67	        debug_assert_eq!(
68	            self.is_ready(),
69	            false,
70	            "doing parallel work on completed job"
71	        );
72	        log::trace!("processing parallel receive job");
73	
74	        // decrypt
75	        {
76	            // closure for locking
77	            let job = &self.0;
78	            let peer = &job.state.peer;
79	            let mut msg = job.buffer.lock();
80	
81	            // process buffer
82	            let ok = (|| {
83	                // cast to header followed by payload
84	                let (header, packet): (LayoutVerified<&mut [u8], TransportHeader>, &mut [u8]) =
85	                    match LayoutVerified::new_from_prefix(&mut msg.1[..]) {
86	                        Some(v) => v,
87	                        None => return false,
88	                    };
89	
90	                // create nonce object
91	                let mut nonce = [0u8; 12];
92	                debug_assert_eq!(nonce.len(), CHACHA20_POLY1305.nonce_len());
93	                nonce[4..].copy_from_slice(header.f_counter.as_bytes());
94	                let nonce = Nonce::assume_unique_for_key(nonce);
95	                // do the weird ring AEAD dance
96	                let key = LessSafeKey::new(
97	                    UnboundKey::new(&CHACHA20_POLY1305, &job.state.keypair.recv.key[..]).unwrap(),
98	                );
99	
100	                // attempt to open (and authenticate) the body
101	                match key.open_in_place(nonce, Aad::empty(), packet) {
102	                    Ok(_) => (),
103	                    Err(_) => return false,
104	                }
105	
106	                // check that counter not after reject
107	                if header.f_counter.get() >= REJECT_AFTER_MESSAGES {
108	                    return false;
109	                }
110	
111	                // check crypto-key router
112	                packet.len() == SIZE_TAG || peer.device.table.check_route(&peer, &packet)
113	            })();
114	
115	            // remove message in case of failure:
116	            // to indicate failure and avoid later accidental use of unauthenticated data.
117	            if !ok {
118	                msg.1.truncate(0);
119	            }
120	        };
121	
122	        // mark ready
123	        self.0.ready.store(true, Ordering::Release);
124	    }
125	}
126	
127	impl<E: Endpoint, C: Callbacks, T: tun::Writer, B: udp::Writer<E>> SequentialJob
128	    for ReceiveJob<E, C, T, B>
129	{
130	    fn is_ready(&self) -> bool {
131	        self.0.ready.load(Ordering::Acquire)
132	    }
133	
134	    fn sequential_work(self) {
135	        debug_assert_eq!(
136	            self.is_ready(),
137	            true,
138	            "doing sequential work on an incomplete job"
139	        );
140	        log::trace!("processing sequential receive job");
141	
142	        let job = &self.0;
143	        let peer = &job.state.peer;
144	        let mut msg = job.buffer.lock();
145	        let endpoint = msg.0.take();
146	
147	        // cast transport header
148	        let (header, packet): (LayoutVerified<&[u8], TransportHeader>, &[u8]) =
149	            match LayoutVerified::new_from_prefix(&msg.1[..]) {
150	                Some(v) => v,
151	                None => {
152	                    // also covers authentication failure (will fail to parse header)
153	                    return;
154	                }
155	            };
156	
157	        // check for replay
158	        if !job.state.protector.lock().update(header.f_counter.get()) {
159	            log::debug!("inbound worker: replay detected");
160	            return;
161	        }
162	
163	        // check for confirms key
164	        if !job.state.confirmed.swap(true, Ordering::SeqCst) {
165	            log::debug!("inbound worker: message confirms key");
166	            peer.confirm_key(&job.state.keypair);
167	        }
168	
169	        // update endpoint
170	        *peer.endpoint.lock() = endpoint;
171	
172	        // check if should be written to TUN
173	        // (keep-alive and malformed packets will have no inner length)
174	        if let Some(inner) = inner_length(packet) {
175	            if inner + SIZE_TAG <= packet.len() {
176	                let _ = peer.device.inbound.write(&packet[..inner]).map_err(|e| {
177	                    log::debug!("failed to write inbound packet to TUN: {:?}", e);
178	                });
179	            }
180	        }
181	
182	        // trigger callback
183	        C::recv(&peer.opaque, msg.1.len(), true, &job.state.keypair);
184	    }
185	}
